import React, { useState, useMemo, useEffect, useRef } from 'react'

// ---------------------------------------------------------------------------
// Self-contained interactive manual viewer.
//
// Renders a `ManuelData` object — chapters of prose blocks plus interactive
// boards (step the solution, or solve it move by move). The data modules under
// ./data are generated by backend/strategy/build_manuel_interactif.py from the
// corpus prose + verified solution lines; this component is the shared reader
// (originally the hand-built "manuel Débutant", refactored to take `data` as a
// prop so every theoretical manual reuses it).
// ---------------------------------------------------------------------------

export interface Run { t: string; b?: number; c?: number; id?: number }

export interface StartState {
  wm: number[]; wk: number[]; bm: number[]; bk: number[]; turn: Side
}

export interface MoveStep {
  n: string; f: number; t: number; c: number[]; path: number[]; p?: boolean
}

export interface Motif { m: string; sev: number; sq: number[]; step?: number }

export interface Position {
  id: string
  ch?: number
  theme?: string
  title: string
  concept?: string
  exp?: string
  pub?: string
  prompt?: string
  start: StartState
  moves: MoveStep[]
  ev?: number
  win?: 'white' | 'black' | 'draw'
  dep?: number
  note?: string
  mot?: Motif[]
}

export type Block =
  | { type: 'board'; id: string; ch: number }
  | { type: 'hr'; ch: number }
  | { type: 'h1' | 'h2' | 'h3' | 'h4' | 'quote' | 'p'; ch: number; runs: Run[] }
  | { type: 'ul' | 'ol'; ch: number; items: Run[][] }
  | { type: 'table'; ch: number; rows: string[][] }

export interface Chapter { n: number; title: string }

export interface ManuelData {
  book: string
  level: string
  chapters: Chapter[]
  blocks: Block[]
  positions: Record<string, Position>
}

type Side = 'white' | 'black'

interface LiveState {
  wm: Set<number>; wk: Set<number>; bm: Set<number>; bk: Set<number>; turn: Side
}

const MOTIF_LABELS: Record<string, string> = {
  coup_de_talon: 'Coup de Talon', coup_philippe: 'Coup Philippe', coup_turc: 'Coup Turc',
  coup_enfilade: 'Enfilade', coup_du_bruleur: 'Brûleur', coup_raphael: 'Coup Raphaël',
  coup_royal: 'Coup Royal', coup_napoleon: 'Coup Napoléon', coup_manoury: 'Coup Manoury',
  coup_express: 'Coup Express', coup_bonnard: 'Coup Bonnard', envoi_a_dame: 'Envoi à dame',
  sacrifice: 'Sacrifice', prise_max_ratee: 'Prise max. ratée',
}

function coord(n: number): { r: number; c: number } {
  const i = n - 1, r = Math.floor(i / 5), c = 2 * (i % 5) + (r % 2 === 0 ? 1 : 0)
  return { r, c }
}
const SQ_AT: Record<number, number> = {}
for (let n = 1; n <= 50; n++) { const { r, c } = coord(n); SQ_AT[r * 10 + c] = n }

function startState(p: Position): LiveState {
  return {
    wm: new Set(p.start.wm), wk: new Set(p.start.wk),
    bm: new Set(p.start.bm), bk: new Set(p.start.bk), turn: p.start.turn,
  }
}
function applyMove(S: LiveState, m: MoveStep): void {
  const isKing = S.wk.has(m.f) || S.bk.has(m.f)
  const isWhite = S.wm.has(m.f) || S.wk.has(m.f)
  ;[S.wm, S.wk, S.bm, S.bk].forEach(s => s.delete(m.f))
  ;(m.c || []).forEach(c => [S.wm, S.wk, S.bm, S.bk].forEach(s => s.delete(c)))
  ;((isKing || m.p) ? (isWhite ? S.wk : S.bk) : (isWhite ? S.wm : S.bm)).add(m.t)
  S.turn = S.turn === 'white' ? 'black' : 'white'
}
function stateAt(p: Position, step: number): LiveState {
  const S = startState(p)
  for (let i = 0; i < step; i++) applyMove(S, p.moves[i])
  return S
}
const nMoves = (p: Position): number => p.moves.length
function moverSide(p: Position, i: number): Side {
  const S = stateAt(p, i), m = p.moves[i]
  return (S.wm.has(m.f) || S.wk.has(m.f)) ? 'white' : 'black'
}
function solverSide(p: Position): Side {
  const t = p.start.turn
  for (let i = 0; i < nMoves(p); i++) if (moverSide(p, i) === t) return t
  return t === 'white' ? 'black' : 'white'
}
function leadStep(p: Position): number {
  let s = 0
  while (s < nMoves(p) && moverSide(p, s) !== solverSide(p)) s++
  return s
}

